import {ANCHOR,SERVICES,STATUSES,seed,metrics,serviceStatus,createIncident,updateIncident,validState} from './domain.js';
import {copy,locales,localizeStatic} from './i18n.js';
const $=s=>document.querySelector(s), key='service-watch-v1';let state=seed(),lang='pt',filter='all',editing=null,storageOK=true,recovered=false;
try {lang=localStorage.getItem('service-watch-lang')||'pt';const raw=localStorage.getItem(key);if(raw){try{const data=JSON.parse(raw);if(validState(data))state=data;else recovered=true;}catch{recovered=true;}}}catch{storageOK=false;}
if(!copy[lang])lang='pt';
const language=document.createElement('select');language.className='language';language.setAttribute('aria-label','Idioma / Language / 言語');language.innerHTML='<option value="pt">Português</option><option value="en">English</option><option value="ja">日本語</option>';language.value=lang;$('header').append(language);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>copy[lang][k];const number=(v,d=0)=>new Intl.NumberFormat(locales[lang],{minimumFractionDigits:d,maximumFractionDigits:d}).format(v);const date=v=>new Intl.DateTimeFormat(locales[lang],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC'}).format(v)+' UTC';
function seeded(text,key){return key&&Object.hasOwn(copy.pt,key)&&copy.pt[key]===text?t(key):text;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}toast(t(storageOK?'saved':'storage'));}
function render(){const hours=Number($('#window').value);const list=SERVICES.map(s=>metrics(state.observations,s.id,hours));const total=list.reduce((n,m)=>n+m.samples,0),ok=list.reduce((n,m)=>n+m.rows.filter(o=>o.ok).length,0);$('#operational').textContent=number(SERVICES.filter(s=>serviceStatus(state,s.id)==='operational').length);$('#availability').textContent=number(ok/total*100,2)+'%';$('#active-count').textContent=number(state.incidents.filter(i=>i.status!=='resolved').length);$('#window-caption').textContent=t('hours').replace('{n}',number(hours));
 $('#services').innerHTML=SERVICES.map((s,index)=>{const m=list[index],status=serviceStatus(state,s.id);const chunks=Array.from({length:Math.min(48,m.rows.length)},(_,i)=>m.rows.slice(Math.floor(i*m.rows.length/Math.min(48,m.rows.length)),Math.floor((i+1)*m.rows.length/Math.min(48,m.rows.length))));return `<article class="service-card"><div class="service-top"><div class="service-name"><span class="service-icon" aria-hidden="true">${s.icon}</span><div><h3>${t(s.id)}</h3><small>${t(index<2?'application':'infra')}</small></div></div><span class="badge ${status}">${t(status)}</span></div><div class="service-values"><div><strong>${m.uptime===null?'—':number(m.uptime,2)+'%'}</strong><small>${t('uptime')}</small></div><div><strong>${m.latency===null?'—':number(m.latency)+' ms'}</strong><small>${t('latency')}</small></div></div><div class="spark" aria-label="${number(m.samples)} ${t('samples')}">${chunks.map(c=>`<span class="${c.some(o=>!o.ok)?'failed':''}" title="${date(c[0].at)} · ${c.filter(o=>o.ok).length}/${c.length}"></span>`).join('')}</div><div class="spark-caption"><span>${t('start')}</span><span>${number(m.samples)} ${t('samples')}</span><span>${t('end')}</span></div></article>`;}).join('');renderIncidents();}
function renderIncidents(){const search=$('#search').value.trim().toLocaleLowerCase(locales[lang]);const items=state.incidents.filter(i=>(filter==='all'||(filter==='resolved')===(i.status==='resolved'))&&`${seeded(i.title,i.titleKey)} ${i.id}`.toLocaleLowerCase(locales[lang]).includes(search));$('#record-count').textContent=`${number(items.length)} ${t('records')}`;$('#incident-list').innerHTML=items.length?items.map(i=>`<details class="incident"><summary><div class="incident-title"><span class="incident-code">${esc(i.id)} · ${t(i.serviceId)}</span><h3>${esc(seeded(i.title,i.titleKey))}</h3><div class="incident-meta">${date(i.createdAt)} · ${t(i.severity)}</div></div><span class="badge ${i.status}">${t(i.status)}</span></summary><div class="incident-body"><ol class="timeline">${i.updates.map(u=>`<li><strong>${t(u.status)}</strong><p>${esc(seeded(u.message,u.messageKey))}</p><time>${date(u.at)}</time></li>`).join('')}</ol>${i.status==='resolved'?'':`<button class="small-button" data-update="${esc(i.id)}">${t('update')} ↗</button>`}</div></details>`).join(''):`<div class="empty">${t('empty')}</div>`;}
function localize(){localizeStatic(lang);$('#service-select').innerHTML=SERVICES.map(s=>`<option value="${s.id}">${t(s.id)}</option>`).join('');$('#status-select').innerHTML=Object.keys(STATUSES).map(s=>`<option value="${s}">${t(s)}</option>`).join('');$('select[name="severity"]').innerHTML=`<option value="degraded">${t('degraded')}</option><option value="outage">${t('outage')}</option>`;render();}
function openEditor(id=null){editing=id;const form=$('#incident-form');form.reset();$('#form-error').textContent='';$('#create-fields').hidden=!!id;$('#update-fields').hidden=!id;form.elements.title.required=!id;form.elements.title.disabled=!!id;$('#dialog-title').textContent=t(id?'edit':'new');if(id)form.elements.status.value=state.incidents.find(i=>i.id===id).status;$('#editor').showModal();}
$('#new-incident').onclick=()=>openEditor();$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#editor').close();$('#incident-list').onclick=e=>{const button=e.target.closest('[data-update]');if(button)openEditor(button.dataset.update);};$('#incident-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{const now=Math.max(Date.now(),ANCHOR);state=editing?updateIncident(state,editing,data.status,data.message,now):createIncident(state,data,now);save();$('#editor').close();render();}catch(error){const index=copy.pt.errors.indexOf(error.message);$('#form-error').textContent=index<0?error.message:copy[lang].errors[index];}};
$('#window').onchange=render;$('#search').oninput=renderIncidents;$('.tabs').onclick=e=>{const button=e.target.closest('button');if(!button)return;filter=button.dataset.filter;document.querySelectorAll('.tabs button').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});renderIncidents();};$('#reset').onclick=()=>$('#reset-dialog').showModal();$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{state=seed();filter='all';$('#search').value='';$('#window').value='24';document.querySelectorAll('.tabs button').forEach(b=>{b.classList.toggle('selected',b.dataset.filter==='all');b.setAttribute('aria-pressed',String(b.dataset.filter==='all'));});save();$('#reset-dialog').close();render();toast(t(storageOK?'reset':'storage'));};language.onchange=()=>{lang=language.value;try{localStorage.setItem('service-watch-lang',lang);}catch{toast(t('storage'));}localize();};document.querySelectorAll('.tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='all')));localize();if(recovered)toast(t('recovered'));else if(!storageOK)toast(t('storage'));
